import React, { useState } from 'react';
import './Tabs.css';

const tabs = [
  { title: 'One Punch Man', panelId: 'tab1-panel', imageSrc: 'https://giffiles.alphacoders.com/170/170001.gif', imageAlt: 'One Punch Man', imageWidth: 250 },
  { title: 'One Peace', panelId: 'tab2-panel', imageSrc: 'https://media.giphy.com/media/bGmzbqDKcmvyU/giphy.gif', imageAlt: 'Luffy the Pirate king', imageHeight: 150 },
  { title: 'Spongebob', panelId: 'tab3-panel', imageSrc: 'https://media.giphy.com/media/yqMtk0TfjRa5W/giphy.gif', imageAlt: 'Spongebob', imageHeight: 150 },
];

function Tabs() {
  const [selectedTab, setSelectedTab] = useState(0);

  return (
    <div>
      <h4 className='text-center' style={{ color: '#E21549' }}>Vertical tabs with Material design lite</h4>
      <div className="mdl-tabs vertical-mdl-tabs mdl-js-tabs mdl-js-ripple-effect">
        <div className="mdl-grid mdl-grid--no-spacing">
          <div className="mdl-cell mdl-cell--2-col">
            <div className="mdl-tabs__tab-bar">
              {tabs.map((tab, index) => (
                <a
                  href={`#${tab.panelId}`}
                  className={`mdl-tabs__tab ${index === selectedTab ? 'is-active' : ''}`}
                  key={index}
                  onClick={() => setSelectedTab(index)}
                >
                  <span className="hollow-circle"></span>
                  {tab.title}
                </a>
              ))}
            </div>
          </div>
          <div className="mdl-cell mdl-cell--10-col">
            {tabs.map((tab, index) => (
              <div
                className={`mdl-tabs__panel ${index === selectedTab ? 'is-active' : ''}`}
                id={tab.panelId}
                key={index}
              >
                <img
                  src={tab.imageSrc}
                  alt={tab.imageAlt}
                  width={tab.imageWidth || undefined}
                  height={tab.imageHeight || undefined}
                />
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

export default Tabs;
